import XCTest
@testable import KipurseCore

/// t789: the sign-in page (served by pay.kipurse.com because of the SIWE domain) is checked by the phone before it is shown.
final class SigninCheckTests: XCTestCase {
  // pages generated by the gateway's createSignin (t789 release)
  let plain = "<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content=\"width=device-width,initial-scale=1\"><title>Sign in to Kipurse with Coinbase</title>\n<style>body{margin:0;background:#F2F2F7;color:#111;font:17px/1.45 -apple-system,\"PingFang SC\",sans-serif}.w{max-width:480px;margin:0 auto;padding:28px 18px 40px}.c{background:#fff;border-radius:16px;padding:14px 16px;margin:12px 0}.t{font-size:24px;font-weight:700;margin:10px 0}.m{color:#666;font-size:14px}button{display:block;width:100%;border:0;border-radius:14px;padding:15px;font-size:18px;font-weight:600;margin-top:10px;background:#0052FF;color:#fff}</style>\n<div class=w><div class=t>Sign in with Coinbase</div>\n<div class=c>Your Coinbase account (Coinbase wallet) is your Kipurse identity. Kipurse stores no password and does no ID check.</div>\n<div class=c><b>One free signature</b><div class=m>No transaction, no fee. It only proves the account is yours.</div></div>\n<button id=go>Sign in with Coinbase</button><p class=m id=st></p></div>\n<script type=\"application/json\" id=kp-data>{\"id\":\"18703f9a88cd3e27cf518900faba230a\",\"nonce\":\"86c86ee8181f3c6c01650db0\",\"chainId\":8453}</script><script nonce=\"zajclC7tBTXrPhBP\" src=\"/signin.js?v=mvuaz9um\" integrity=\"sha384-QNbm/X1nJaabK6dmly8sf65qfUHAkLgaCJHUfplx99ISQq9mkeXjtHosMwPAoJQ9\"></script></html>"
  let onb = "<!doctype html><html lang=zh><meta charset=utf-8><meta name=viewport content=\"width=device-width,initial-scale=1\"><title>用 Coinbase 登录 Kipurse</title>\n<style>body{margin:0;background:#F2F2F7;color:#111;font:17px/1.45 -apple-system,\"PingFang SC\",sans-serif}.w{max-width:480px;margin:0 auto;padding:28px 18px 40px}.c{background:#fff;border-radius:16px;padding:14px 16px;margin:12px 0}.t{font-size:24px;font-weight:700;margin:10px 0}.m{color:#666;font-size:14px}button{display:block;width:100%;border:0;border-radius:14px;padding:15px;font-size:18px;font-weight:600;margin-top:10px;background:#0052FF;color:#fff}</style>\n<div class=w><div class=t>用 Coinbase 登录</div>\n<div class=c>你的 Coinbase 账户（Coinbase wallet）就是你在启付的身份。启付不存密码，也不做实名。</div>\n<div class=c><b>① 登录：签一个名，免费</b><div class=m>不发生交易，只确认这个账户是你的。</div></div>\n<div class=c id=setupcard><b>② 新用户：同一页里再点一次「开通」</b><div class=m>创建你的启付钱包，并设好 AI 默认上限（每笔 5 · 每天 20 · 总额 100 USDC · 90 天，可以随时在 App 里自己改）。首次开通的手续费由 Kipurse 代付，你付 $0；如果免费名额用完，会先告诉你，不会自动扣你的钱。老用户只需第 ① 步。</div></div>\n<button id=go>用 Coinbase 登录</button><p class=m id=st></p></div>\n<script type=\"application/json\" id=kp-data>{\"id\":\"b3823fce9822cf5319f891559e6f3f2b\",\"nonce\":\"a17f01f097bc8e4620f7a234\",\"chainId\":8453}</script><script nonce=\"7Yor8QfyFJQddJHI\" src=\"/signin.js?v=mvuaz9um\" integrity=\"sha384-QNbm/X1nJaabK6dmly8sf65qfUHAkLgaCJHUfplx99ISQq9mkeXjtHosMwPAoJQ9\"></script></html>"
  func testPublishedPagesPass() {
    XCTAssertNil(SigninCheck.htmlProblem(plain)); XCTAssertNil(SigninCheck.htmlProblem(onb))
  }
  func testTamperedPagesFail() {
    XCTAssertEqual(SigninCheck.htmlProblem(plain.replacingOccurrences(of: SigninCheck.scriptSRI, with: "sha384-AAAA")), "bundle_sri")
    XCTAssertEqual(SigninCheck.htmlProblem(plain.replacingOccurrences(of: "</html>", with: "<script>steal()</script></html>")), "script_count")
    XCTAssertEqual(SigninCheck.htmlProblem(plain.replacingOccurrences(of: "src=\"/signin.js", with: "src=\"https://evil.example/signin.js")), "bundle_tag")
    XCTAssertEqual(SigninCheck.htmlProblem(plain.replacingOccurrences(of: "</html>", with: "<iframe src=x></iframe></html>")), "forbidden")
    XCTAssertEqual(SigninCheck.htmlProblem(plain.replacingOccurrences(of: "<button id=go>", with: "<button id=go onclick=\"x()\">")), "handler")
    XCTAssertEqual(SigninCheck.htmlProblem(plain.replacingOccurrences(of: "</html>", with: "<meta http-equiv=refresh content=\"0;url=https://evil.example\"></html>")), "forbidden")
    let noIntegrity = plain.replacingOccurrences(of: " integrity=\"\(SigninCheck.scriptSRI)\"", with: "")
    XCTAssertEqual(SigninCheck.htmlProblem(noIntegrity), "bundle_tag")
  }
  func testBundleHash() {
    XCTAssertEqual(SigninCheck.scriptProblem(Data("console.log(1)".utf8)), "bundle_hash")
    XCTAssertEqual(SigninCheck.sri(Data("abc".utf8)), "sha384-ywB1P0WjXou1oD1pmsZQBycsMqsO3tFjGotgWkP/W+2AhgcroefMI1i67KE0yCWn")
  }
}
